## 3. Concrete Refactor – “Secure Starter” version of `app.js`

Below is a **drop‑in replacement** that addresses all the points above while keeping the original functionality intact.

```js
// app.js – Secure Starter (OWASP‑compliant)

require('dotenv').config();                // Load env vars from .env (never commit secrets)
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// -------------------------------------------------
// 1️⃣  Core Security Middleware
// -------------------------------------------------
app.disable('x-powered-by');                     // Hide Express banner
app.set('trust proxy', 1);                       // Needed if behind a reverse‑proxy (e.g., Heroku, Nginx)

// Helmet – sets dozens of security headers (CSP, HSTS, X‑Content‑Type‑Options, etc.)
app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'", 'https:'],
        imgSrc: ["'self'", 'data:'],
        connectSrc: ["'self'"],
        objectSrc: ["'none'"],
        upgradeInsecureRequests: [], // forces HTTPS if a request comes in over HTTP
      },
    },
  })
);

// CORS – tightly restrict origins (adjust for your front‑end)
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [], // e.g., "https://app.example.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting – mitigates brute‑force & DoS
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/api/', apiLimiter); // apply only to API routes (you can broaden as needed)

// -------------------------------------------------
// 2️⃣  Body & Query Parsing + Validation helpers
// -------------------------------------------------
app.use(express.json()); // parse JSON bodies

// Centralised error formatter for validation results
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// -------------------------------------------------
// 3️⃣  Simple JWT Auth Middleware (replace with your strategy)
// -------------------------------------------------
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401); // No token

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token
    req.user = user; // attach payload for later RBAC checks
    next();
  });
}

// -------------------------------------------------
// 4️⃣  Routes
// -------------------------------------------------

// Health endpoint – keep it public but thin
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example protected route – listing users (requires auth)
app.get(
  '/api/users',
  authenticateToken,
  (req, res) => {
    // In a real app this would be a DB call (use parameterised queries!)
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// -------------------------------------------------
// 5️⃣  Request Logging (morgan -> winston)
// -------------------------------------------------
const winston = require('winston');
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.Console()],
});
app.use(
  morgan('combined', {
    stream: {
      write: (message) => logger.info(message.trim()),
    },
  })
);

// -------------------------------------------------
// 6️⃣  Centralised Error Handler (must be AFTER routes)
// -------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full stack for ops (never expose to clients)
  logger.error(err.stack);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message,
  });
});

// -------------------------------------------------
// 7️⃣  Server start – respect ENV port & enforce HTTPS via proxy
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What changed & why?

| Change | Reason (OWASP) |
|--------|----------------|
| **`dotenv`** | Keeps secrets out of source (A02 Cryptographic Failures). |
| **Helmet** | Sends security headers → mitigates XSS, click‑jacking, MIME sniffing (A05). |
| **CORS whitelist** | Prevents browsers from letting any site call your API (A01). |
| **Rate limiting** | Thwarts credential‑stuffing / DoS (A04, A06). |
| **`authenticateToken` middleware** | Introduces authentication, enables RBAC (A01, A07). |
| **Input validation skeleton** (`express-validator`) | Guarantees that future query/body data is sanitized (A03). |
| **Centralised error handling** | Hides stack traces from the client, logs them for ops (A09). |
| **Morgan + Winston** | Structured logging for detection/response (A09). |
| **`trust proxy` & removal of `x-powered-by`** | Prevents leakage of server tech and enables correct client IP for rate‑limit (A05). |
| **Environment‑driven port** | Allows deployment behind containers / reverse proxy (no hard‑coded values). |
| **HTTPS enforcement via Helmet HSTS** | Encourages browsers to always use TLS (A02). |

---

## 4. Checklist for Ongoing Development

| ✅ | Item |
|----|------|
| **Dependency hygiene** | Run `npm audit` on every PR; keep `package-lock.json` committed. |
| **Static analysis** | Add `npm run lint` (`eslint` with `plugin-security`) and `npm run snyk-test` (or GitHub Dependabot). |
| **Secrets management** | Store `JWT_SECRET`, DB credentials, etc., in a secret manager (AWS Secrets Manager, Vault). |
| **Automated tests** | Write integration tests that assert 401/403 on protected routes. |
| **CI/CD** | Enforce lint, test, and audit steps before merging. |
| **Infrastructure** | Deploy behind an HTTPS‑terminating load balancer (NGINX, Cloudflare). |
| **Monitoring** | Ship logs to a SIEM; set alerts on 5xx spikes, auth failures. |
| **Rate‑limit and throttling** | Review the limiter thresholds per endpoint as traffic grows. |
| **Content‑Security‑Policy (CSP)** | Adjust the `helmet.contentSecurityPolicy` directives when you start serving HTML/JS. |
| **CSRF protection** | If you later add state‑changing POST/PUT/DELETE routes with cookie‑based auth, enable `csurf`. |

---

## 5. How to Introduce the Changes Incrementally

If you cannot switch everything over at once, you can adopt a **phased approach**:

1. **Phase 1 – Hardening basics**  
   - Add `helmet`, `cors`, `trust proxy`, and remove `x-powered‑by`.  
   - Add `dotenv` and move the port to an env var.  

2. **Phase 2 – Logging & Error handling**  
   - Plug in `morgan` → `winston`.  
   - Add the central error handler.

3. **Phase 3 – Authentication**  
   - Implement JWT login route (`/api/auth/login`) that returns a token.  
   - Protect `/api/users` with the `authenticateToken` middleware.

4. **Phase 4 – Rate‑limiting & Validation**  
   - Add the `express-rate-limit` middleware.  
   - Introduce `express-validator` or `joi` for any query/body parameters you add later.

5. **Phase 5 – Continuous security**  
   - Set up `npm audit`, `dependabot`, CI linting, and a monitoring pipeline.

You can copy‑paste the **full secure starter** code above into `app.js` (it is fully functional for the existing endpoints) and then remove the old version.  After deploying, verify:

```bash
# 1. Health endpoint
curl -i https://your‑domain.com/health

# 2. Unauthorized user list – should return 401
curl -i https://your‑domain.com/api/users

# 3. Authorized request (replace <token> with a valid JWT)
curl -i -H "Authorization: Bearer <token>" https://your‑domain.com/api/users
```

If the responses match expectations, you’ve successfully hardened the app.

