// app.js – Secure version
// ------------------------------------------------------------
// 1️⃣ Load environment variables (never commit secrets)
// 2️⃣ Harden HTTP headers (Helmet)
// 3️⃣ Enable CORS only for trusted origins
// 4️⃣ Add rate‑limiting & basic request logging
// 5️⃣ Centralised error handling (no stack traces in prod)
// 6️⃣ Protect the /users endpoint with JWT‑based auth
// ------------------------------------------------------------

require('dotenv').config();                 // <-- .env file with e.g. JWT_SECRET, NODE_ENV
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { body, param, validationResult } = require('express-validator');

const app = express();

// ------------------------------------------------------------
// 1️⃣ Global middleware
// ------------------------------------------------------------
app.use(helmet());                          // security headers (CSP, HSTS, etc.)
app.use(express.json());                   // body parser for JSON payloads

// Allow only trusted origins (adjust to your domain)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // e.g. "https://myapp.com"
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
  })
);

// Logging – concise in prod, verbose in dev
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined')); // Apache‑style logs for SIEM
}

// ------------------------------------------------------------
// 2️⃣ Rate limiting (prevent brute‑force, DoS)
// ------------------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/api/', apiLimiter); // apply to all API routes (prefix later)


// ------------------------------------------------------------
// 3️⃣ Simple JWT auth middleware (replace with your auth scheme)
// ------------------------------------------------------------
function authenticateJwt(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }
  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // e.g. { sub: userId, role: 'admin' }
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// ------------------------------------------------------------
// 4️⃣ Routes
// ------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
