// ------------------------------------------------------------
// 5️⃣ Centralised error handler (no stack trace in prod)
// ------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full error for the dev/ops team
  console.error(err);
  const response = {
    error: 'Internal Server Error',
  };
