app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        // Adjust as needed for static assets or external APIs
      },
    },
    // Enable HSTS (only works over HTTPS)
    hsts: { maxAge: 31536000, includeSubDomains: true },
  })
);

// CORS – configure origins you trust (change to your front‑end domain)
app.use(cors({ origin: process.env.CORS_ORIGIN || 'http://localhost:3000' }));

