app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Rate limiting – protect all routes (adjust limits as appropriate)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

/* --------------------------------------------------------------
   3️⃣  Authentication middleware (example using JWT)
   -------------------------------------------------------------- */
// Expected header: Authorization: Bearer <token>
function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1];
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user; // attach decoded payload
    next();
  });
}

/* --------------------------------------------------------------
   4️⃣  Input validation helper
   -------------------------------------------------------------- */
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Return the first error for simplicity; you can return all
    return res.status(400).json({ error: errors.array()[0].msg });
  }
  next();
}

/* --------------------------------------------------------------
   5️⃣  Routes
   -------------------------------------------------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
