  }
);

/**
 * Example of a safe POST endpoint with validation & sanitisation.
 * Demonstrates how to avoid Injection issues.
 */
app.post('/users',
  authenticateJWT,
  [
    body('name')
      .trim()
      .isLength({ min: 1 }).withMessage('Name is required')
      .escape(),
