```js
// --------------------------------------------------------------
// app.js – Hardened Express server (OWASP Top 10 mitigations)
// --------------------------------------------------------------

require('dotenv').config();                 // Load environment vars from .env (never commit secrets)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const jwt = require('express-jwt');        // For protected routes (install `express-jwt`)

const app = express();

// ---------- Security Middleware ----------
app.use(helmet());                         // Sets secure HTTP headers
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') || [] })); // Restrict origins
app.use(express.json());                   // Body parser for future POST/PUT
app.use(morgan('combined'));               // Request logging

// Global rate limiter (adjust limits per your traffic profile)
const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 120,            // max 120 requests per minute per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(apiLimiter);

// ---------- Auth Middleware (optional, can be toggled) ----------
const jwtSecret = process.env.JWT_SECRET || 'fallback-secret-please-set';

// Protect the /users endpoint – only authenticated users with role "admin"
function requireRole(role) {
  return (req, res, next) => {
    if (req.user && req.user.role === role) return next();
    return res.status(403).json({ error: 'Forbidden' });
  };
}

// Apply JWT validation to routes that need protection
app.use(
  '/users',
  jwt({ secret: jwtSecret, algorithms: ['HS256'] }).unless({ path: ['/health'] })
);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', requireRole('admin'), (req, res) => {
  // In a real app this would come from a DB, filtered by permissions.
  // Emails are considered PII – only return to admins.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---------- Error handling ----------
app.use((err, req, res, next) => {
  // Log the full error for ops, but hide details from the client.
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({ error: status === 500 ? 'Internal Server Error' : err.message });
});

// ---------- Start server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

