### 2.1 Add Core Middleware (Helmet, CORS, JSON body parser)

```js
// app.js – top of file
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { json } = require('express'); // built‑in body parser (since Express 4.16+)

// Rate limiter (basic example: 100 req / 15 min per IP)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

const app = express();

// Apply security middle‑wares
app.use(helmet());                // sets X‑Content‑Type‑Options, CSP, HSTS, etc.
app.use(cors({                     // restrict origins to your front‑end
  origin: process.env.ALLOWED_ORIGIN || 'https://myapp.example.com',
  methods: ['GET', 'POST'],
}));
app.use(limiter);                 // basic DoS protection
app.use(json());                  // parse JSON bodies for future POST/PUT routes
```

> **Why?**  
> * **Helmet** automatically adds OWASP‑recommended headers.  
> * **CORS** prevents browsers from allowing other origins to call your API.  
> * **Rate limiting** mitigates brute‑force and simple DoS attacks.  
> * **JSON parser** guarantees that body parsing is consistent and won’t accept malformed payloads.

