## Recommended Way Forward: Move Secrets to a Managed Store

Below are three common secret‑management patterns and concrete code snippets you can drop into `app.js` (or a dedicated `config.js`) to replace direct `.env` usage.

### 1️⃣ AWS Secrets Manager (or Parameter Store)

**Prereqs** – IAM role/policy allowing `secretsmanager:GetSecretValue` (or `ssm:GetParameter`).

```bash
npm i @aws-sdk/client-secrets-manager
```

```js
// config.js  (example)
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Fetch a secret JSON object from AWS Secrets Manager.
 * Caches the value in‐memory for the lifetime of the process (good for most Lambda / container setups).
 */
let secretCache = null;
async function loadSecrets() {
  if (secretCache) return secretCache;

  const command = new GetSecretValueCommand({ SecretId: process.env.SECRET_ID || 'my-app-prod' });
  const response = await client.send(command);
  const secretString = response.SecretString;   // expects a JSON string
  secretCache = JSON.parse(secretString);
  return secretCache;
}

module.exports = { loadSecrets };
```

**Usage in `app.js`**

```js
const { loadSecrets } = require('./config');

(async () => {
  const secrets = await loadSecrets();   // resolve before listening
  // e.g. connect to the DB
  const pool = new pg.Pool({ connectionString: secrets.DATABASE_URL });
  // store JWT secret, Stripe key, etc. in `secrets`
})();
```

### 2️⃣ HashiCorp Vault (KV v2)

```bash
npm i node-vault
```

```js
// vaultConfig.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'https://vault.mycompany.com',
  token: process.env.VAULT_TOKEN,   // ideally injected by the orchestrator (K8s, Nomad, etc.)
});

async function getSecrets(path = 'secret/data/my-app') {
  const result = await vault.read(path);
  // Vault KV v2 returns { data: { data: {...}, metadata: {...} } }
  return result.data.data;
}

module.exports = { getSecrets };
```

> **Tip:** When running in Kubernetes, use the Vault Agent side‑car injector to automatically write a short‑lived token into a file and point `VAULT_TOKEN` there.

### 3️⃣ Google Cloud Secret Manager

```bash
npm i @google-cloud/secret-manager
```

```js
// gcpSecrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function accessSecret(name) {
  const [version] = await client.accessSecretVersion({ name });
  const payload = version.payload.data.toString('utf8');
  return JSON.parse(payload);   // expects a JSON object
}

module.exports = { accessSecret };
```

**Calling code**

```js
const { accessSecret } = require('./gcpSecrets');

(async () => {
  const secrets = await accessSecret('projects/my-project/secrets/app-config/versions/latest');
  // use secrets.DATABASE_URL, secrets.STRIPE_SECRET_KEY, etc.
})();
```

