## Example – Minimal Production‑Ready `app.js` Using AWS Secrets Manager

```js
// app.js – production‑ready snippet
require('dotenv').config();               // only for non‑secret config (e.g., LOG_LEVEL)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const pinoHttp = require('pino-http');
const { loadSecrets } = require('./config'); // <-- AWS Secrets Manager helper

const app = express();
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
app.use(pinoHttp({ logger }));
app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGIN || 'https://myapp.example.com' }));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
app.use(express.json());

// -------------------------------------------------
// Load secrets BEFORE we start listening
// -------------------------------------------------
(async () => {
  const secrets = await loadSecrets();   // throws if unreachable → container fails fast

  // Example: initialise DB pool with the secret
  const { Pool } = require('pg');
  const db = new Pool({ connectionString: secrets.DATABASE_URL });

  // Attach the secret object to the request for later routes (optional)
  app.use((req, res, next) => {
    req.secrets = secrets;
    req.db = db;
    next();
  });

  // ---------- Routes ----------
  app.get('/health', (req, res) => {
    logger.info('Health check');
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // /users should be authenticated; JWT secret comes from the secret manager
  const auth = require('./auth'); // JWT middleware that reads req.secrets.JWT_SECRET internally
  app.get('/users', auth, (req, res) => {
    const isAdmin = req.auth?.role === 'admin';
    const users = [
      { id: 1, name: 'Alice', email: isAdmin ? 'alice@example.com' : undefined },
      { id: 2, name: 'Bob',   email: isAdmin ? 'bob@example.com'   : undefined },
    ];
    res.json(users);
  });

  // ---------- Error handling ----------
  app.use((err, req, res, next) => {
    logger.error(err);
    const status = err.status || 500;
    res.status(status).json({ error: status === 500 ? 'Internal Server Error' : err.message });
  });

  // ---------- Start server ----------
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => logger.info(`Server running on port ${PORT}`));
})();
```

*Key take‑aways*:  
- **Secrets never live in the repository.**  
- **Loading is done at runtime** from a central secret store.  
- **Only a short‑lived token / IAM role** is required for the container, reducing blast‑radius if the image is compromised.  

