Below is a **complete, production‑ready skeleton** incorporating all the recommendations. You can replace the existing file with this version (or cherry‑pick the parts you need).

```js
/**
 * Secure Express Application – OWASP Top‑10 Hardened
 * -------------------------------------------------
 * Keep secret values (JWT secret, DB credentials, etc.) in environment variables.
 */

require('dotenv').config();               // Load .env (if present)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { body, param, validationResult } = require('express-validator');
const { createLogger, transports, format } = require('winston');

const app = express();

// ---------- Logger ----------
const logger = createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: format.combine(format.timestamp(), format.json()),
  transports: [new transports.Console()],
});

// ---------- Middleware ----------
app.use(helmet());

// CORS – adjust ALLOWED_ORIGINS in .env
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

app.use(express.json({ limit: '100kb' }));
app.use(morgan('combined', { stream: { write: (msg) => logger.info(msg.trim()) } }));

// Rate limiting – 100 req / 15 min per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, try again later.' },
});
app.use(limiter);

// ---------- Auth ----------
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  logger.error('JWT_SECRET not defined – aborting startup');
  process.exit(1);
}
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid/expired token' });
    req.user = user;
    next();
  });
}

// ---------- Utility ----------
function maskEmail(email) {
  const [local, domain] = email.split('@');
  return `${local[0]}***@${domain}`;
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example protected endpoint – returns masked data
app.get('/users', authenticateToken, (req, res) => {
  // In a real service fetch from DB and respect RBAC
  const users = [
    { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
    { id: 2, name: 'Bob',   email: maskEmail('bob@example.com') },
  ];
  res.json(users);
});

// Example of a validated, protected UPDATE endpoint
app.put(
  '/users/:id',
  authenticateToken,
  [
    param('id').isInt({ gt: 0 }).toInt(),
    body('email').optional().isEmail().normalizeEmail(),
    body('name').optional().trim().isLength({ min: 1, max: 100 }),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    // TODO: update user in DB here
    res.json({ message: `User ${req.params.id} updated` });
  }
);

// ---------- Global Error Handler ----------
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { error: err.stack || err });
  const response = { error: 'Internal Server Error' };
  if (process.env.NODE_ENV !== 'production') {
    response.message = err.message;
    response.stack = err.stack;
  }
  res.status(err.status || 500).json(response);
});

// ---------- Server Startup ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

module.exports = app;
```

