## Recommendations & Sample Refactored `app.js`

Below is a **secure‑by‑default** rewrite that addresses all of the above points.  You can copy‑paste this into `app.js` (or a new file) and adjust the secret/key values to your environment.

```js
/**
 * Secure Express application – OWASP Top 10 mitigations
 * ----------------------------------------------------
 * 1. Secure HTTP headers (helmet)
 * 2. Hide X‑Powered‑By
 * 3. Enable CORS with a whitelist
 * 4. Rate limiting (express-rate-limit)
 * 5. Input validation (express-validator)
 * 6. Centralised error handling
 * 7. Authentication & RBAC (JWT example)
 * 8. HTTPS enforcement (if behind a reverse‑proxy)
 * 9. Logging (morgan & winston)
 * 10. Graceful shutdown
 */

require('dotenv').config();               // keep secrets out of source code
const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');
const jwt    = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// -------------------------------------------------
// 1. Global security middleware
// -------------------------------------------------
app.use(helmet());                         // adds CSP, HSTS, Referrer‑Policy, etc.
app.disable('x-powered-by');               // hide framework fingerprint

// -------------------------------------------------
// 2. CORS – allow only trusted origins (example)
// -------------------------------------------------
const whitelist = (process.env.CORS_ALLOWED_ORIGINS || '').split(',');
app.use(cors({
  origin: (origin, cb) => {
    // allow non‑browser (e.g., curl, health checks) requests
    if (!origin || whitelist.includes(origin)) {
      cb(null, true);
    } else {
      cb(new Error('Not allowed by CORS'));
    }
  }
}));

// -------------------------------------------------
// 3. Body parsing (JSON) – limit size to mitigate DoS
// -------------------------------------------------
app.use(express.json({ limit: '10kb' })); // reject huge payloads

// -------------------------------------------------
// 4. Rate limiting – basic protection against brute‑force & DoS
// -------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // max 100 requests per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});
app.use('/users', apiLimiter);   // apply to sensitive endpoint
app.use('/health', apiLimiter);  // optional: protect health endpoint

// -------------------------------------------------
// 5. Structured logging
// -------------------------------------------------
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    // new winston.transports.File({ filename: 'combined.log' })
  ]
});
app.use(morgan('combined', { stream: { write: msg => logger.info(msg.trim()) } }));

// -------------------------------------------------
// 6. Simple JWT authentication middleware (example)
// -------------------------------------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // attach user info for RBAC checks later
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// -------------------------------------------------
// 7. Input validation helpers
// -------------------------------------------------
const validateUserId = [
  param('id').isInt({ gt: 0 }).withMessage('User id must be a positive integer'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

// -------------------------------------------------
// 8. Routes
// -------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example of a protected resource – only authenticated users can list users
app.get('/users', authenticate, (req, res) => {
  // In a real app, fetch from DB with proper RBAC check (e.g., admin role)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// Example of a parameterised endpoint with validation
app.get('/users/:id',
  authenticate,
  validateUserId,
  (req, res) => {
    const userId = Number(req.params.id);
    // stub: fetch from DB safely (parameterised query / ORM)
    const user = { id: userId, name: 'Alice', email: 'alice@example.com' };
    res.json(user);
  }
);

// -------------------------------------------------
// 9. Central error handler (do not leak stack traces)
// -------------------------------------------------
app.use((err, req, res, next) => {
  logger.error(err);
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// -------------------------------------------------
// 10. Start server (HTTPS should be terminated upstream)
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

