### Sample Refactor to Use AWS Secrets Manager (illustrative)

```js
// secret-loader.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Retrieve a secret and inject it into process.env.
 * secretId – the AWS Secrets Manager identifier (e.g., "myapp/prod").
 * Returns a Promise that resolves when all keys are set.
 */
async function loadSecrets(secretId) {
  const cmd = new GetSecretValueCommand({ SecretId: secretId });
  const data = await client.send(cmd);

  // Secrets Manager stores a JSON string; parse it.
  const secretObj = JSON.parse(data.SecretString);
  Object.entries(secretObj).forEach(([k, v]) => {
    if (!process.env[k]) {      // do not overwrite already‑provided vars
      process.env[k] = v;
    }
  });
}

// Export a ready‑to‑await wrapper
module.exports = { loadSecrets };
```

