```js
// config.js
/**
 * Central configuration module.
 * Loads values from the environment (or a safe fallback for local dev).
 * Never reads a .env file directly in production.
 */

const env = process.env;

// Helper to ensure required variables exist
function required(name) {
  if (!env[name]) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return env[name];
}

// Export only the values your app needs.
module.exports = {
  // Example: database connection string
  databaseUrl: required('DATABASE_URL'),

  // AWS credentials (if you use the SDK, it can also read from the default provider chain)
  aws: {
    accessKeyId: required('AWS_ACCESS_KEY_ID'),
    secretAccessKey: required('AWS_SECRET_ACCESS_KEY'),
  },

  // Third‑party API keys (use the SDK's built‑in env handling when possible)
  anthropicApiKey: required('ANTHROPIC_API_KEY'),
  stripeSecretKey: required('STRIPE_SECRET_KEY'),
  logfireToken: required('LOGFIRE_TOKEN'),

  // Misc settings
  nodeEnv: env.NODE_ENV || 'development',
  port: parseInt(env.PORT, 10) || 3000,
};
```

**How to use it in `app.js`:**

```js
// app.js
const express = require('express');
const helmet = require('helmet');            // Secure HTTP headers
const morgan = require('morgan');            // Request logging
const config = require('./config');          // Load validated config

const app = express();

// Middleware stack
app.use(helmet());               // A01‑B03 hardening
app.use(express.json());         // Body parser (helps with input validation later)
app.use(morgan('combined'));     // A09 logging (pipe to a secure log sink)

