    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

const PORT = config.port;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

#### Key Points of This Pattern

1. **Explicit validation** – The `required()` helper throws early if a secret is missing, avoiding silent fallback to undefined values.
2. **No hard‑coded fallbacks** – In production you’ll never accidentally run with a dummy secret.
3. **Centralised config** – All secret usage goes through a single module, making it easy to replace the source (e.g., switch to AWS Secrets Manager) without touching the rest of the codebase.
4. **Compatibility with containers / CI** – Environment variables can be injected by the orchestrator (Kubernetes `Secret` object, Docker `--env-file`, CI secret masking).

