```js
// config.js (add to existing module)
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadAwsSecret(name) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  const cmd = new GetSecretValueCommand({ SecretId: name });
  const { SecretString } = await client.send(cmd);
  return JSON.parse(SecretString);
}

// Example: lazy‑load DB credentials
let cachedDbCreds;
async function getDbCreds() {
  if (!cachedDbCreds) {
    cachedDbCreds = await loadAwsSecret('prod/dbCredentials');
  }
  return cachedDbCreds;
}

module.exports = {
  // …
  getDbCreds,
};
```

Now the runtime never sees the raw secret in an environment variable; the SDK fetches it securely from AWS.

