// app.js – hardened Express API (example implementation)
// ------------------------------------------------------------

require('dotenv').config();                 // 1️⃣ env vars
const express = require('express');
const helmet  = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');
const pino    = require('pino');
const pinoHttp = require('pino-http');
const { verifyToken } = require('./auth'); // JWT utils (see auth.js)
const logger  = pino({ level: process.env.LOG_LEVEL || 'info' });

const app = express();

// ------------------------------------------------------------
// 2️⃣ Global middleware
// ------------------------------------------------------------
app.use(helmet());                          // security headers
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://my-frontend.example.com',
  credentials: true,
}));
app.use(express.json());                  // parse JSON bodies

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));

// Request logging
app.use(pinoHttp({ logger }));

// ------------------------------------------------------------
// 3️⃣ HTTPS enforcement (production only)
// ------------------------------------------------------------
if (process.env.NODE_ENV === 'production') {
  app.set('trust proxy', 1);
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
  });
}

// ------------------------------------------------------------
// 4️⃣ Helper: auth middleware
// ------------------------------------------------------------
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = verifyToken(token);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// ------------------------------------------------------------
// 5️⃣ Routes
// ------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', requireAuth, (req, res) => {
  // In real world fetch from DB, apply RBAC checks, etc.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Example RBAC: hide e‑mail for non‑admin users
  if (req.user.role !== 'admin') {
    users.forEach(u => delete u.email);
  }

  res.json(users);
});

// ------------------------------------------------------------
// 6️⃣ Global error handler (must be last)
// ------------------------------------------------------------
app.use((err, _req, res, _next) => {
  logger.error(err);
  const status = err.status || 500;
  res.status(status).json({ error: err.message || 'Internal Server Error' });
});

// ------------------------------------------------------------
// 7️⃣ Server start & graceful shutdown
// ------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

function shutdown() {
  logger.info('Graceful shutdown initiated');
  server.close(() => {
    logger.info('All connections closed');
    process.exit(0);
  });
  setTimeout(() => process.exit(1), 10_000);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT',  shutdown);

module.exports = app;
```

