## Integrating Secrets with the Existing Express App  

Below is a **light‑weight bootstrap** that wires secret loading into the server startup while preserving the clean separation of concerns you already have.

```js
// bootstrap.js
require('dotenv').config({ path: '.env' });   // non‑secret config only

const { loadSecrets } = require('./secrets/awsSecrets'); // or vault/gcp

(async () => {
  try {
    const secrets = await loadSecrets();      // <-- fetch from secrets manager
    // Optional: copy into process.env for legacy libs that read env directly
    Object.assign(process.env, secrets);

    // Import the Express app *after* secrets are loaded
    const app = require('./app');

    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
      console.log(`✅ Server listening on ${PORT}`);
    });

    // Graceful shutdown (same as previously shown)
    const shutdown = () => {
      console.log('🛑 Shutting down...');
      server.close(() => process.exit(0));
    };
    process.on('SIGTERM', shutdown);
    process.on('SIGINT', shutdown);
  } catch (err) {
    console.error('❌ Failed to start server – secret loading error:', err);
    process.exit(1);
  }
})();
```

**How to run:**  

```bash
node bootstrap.js
```

You can replace `bootstrap.js` with a `npm start` script in `package.json`:

```json
"scripts": {
  "start": "node bootstrap.js"
}
```

