> *`dotenv` is used to load secrets from `.env`; `jsonwebtoken` for JWT auth; `bcryptjs` for password hashing (future‑proof).*

### 3.2 Updated `app.js`

```js
// app.js – Secure version of the original demo server
// ---------------------------------------------------
// Purpose: expose a health endpoint and a protected /users endpoint.
// Security features added:
//   • Helmet for secure HTTP headers
//   • CORS with strict origin whitelist
//   • Rate limiting (brute‑force mitigation)
//   • Request logging (morgan)
//   • Basic JWT authentication (demo only)
//   • Removal of X-Powered-By header & other misconfigurations
//   • Centralised error handling

require('dotenv').config();                     // Load .env variables
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();

// ---------- 1. Global Middleware ----------
app.use(helmet());                               // Secure HTTP headers (CSP, HSTS, etc.)
app.disable('x-powered-by');                     // Hide framework details

// CORS – only allow trusted origins (adjust as needed)
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser requests (e.g., CURL) when origin is undefined
      if (!origin || allowedOrigins.includes(origin)) {
        return callback(null, true);
      }
      return callback(new Error('Not allowed by CORS'));
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// Rate limiting – 100 requests per 15‑minute window per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Body parsing (needed when you later accept POST/PUT)
app.use(express.json());

// Structured request logging
app.use(morgan('combined'));

// ---------- 2. Helper: JWT auth middleware ----------
/**
 * Simple JWT verification. In production you would store the secret in a
 * secret manager / Vault and rotate it regularly.
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Expected: "Bearer <token>"
  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user; // Payload may contain role, sub, etc.
    next();
  });
}

// ---------- 3. Routes ----------
app.get('/health', (req, res) => {
  // No sensitive data in health checks; keep the response minimal
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Protected endpoint – only authenticated users can retrieve the list.
 * In a real app you would also check the user's role (e.g., admin) before
 * returning PII.
 */
app.get('/users', authenticateToken, (req, res) => {
  // Example static data; normally you would fetch from a DB with parameterised queries.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/**
 * Demo login endpoint – issues a short‑lived JWT.
 * In production you would verify credentials against a DB with hashed passwords.
 */
app.post('/login', (req, res) => {
  const { email, password } = req.body;
  // *** NOTE: This is a placeholder! *** Replace with real credential check.
  if (email === 'alice@example.com' && password === 'password123') {
    const payload = { sub: 1, name: 'Alice', role: 'user' };
    const token = jwt.sign(payload, process.env.JWT_SECRET, { expiresIn: '1h' });
    return res.json({ token });
  }
  return res.status(401).json({ error: 'Invalid credentials' });
});

// ---------- 4. Centralised Error Handler ----------
app.use((err, _req, res, _next) => {
  // Do not leak stack traces in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };
  if (!isProd && err.stack) response.stack = err.stack;
  res.status(status).json(response);
});

// ---------- 5. Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on ${process.env.NODE_ENV || 'development'} mode, port ${PORT}`);
});

/* Export for testing */
module.exports = app;
```

#### What changed?

| Area | Original | New |
|------|----------|-----|
| **Headers** | None | `helmet()` adds CSP, X‑Content‑Type‑Options, Referrer‑Policy, HSTS (when behind HTTPS), etc. |
| **X‑Powered‑By** | Enabled by default | Disabled (`app.disable('x-powered-by')`). |
| **CORS** | Not defined (allows all) | Whitelist configured via `CORS_ORIGINS` env var. |
| **Rate limiting** | None | `express-rate-limit` (100 req/15 min per IP). |
| **Logging** | `console.log` only on start | `morgan('combined')` for request logs (IP, UA, status). |
| **Authentication** | None | JWT‑based middleware protecting `/users`. |
| **Login (demo)** | N/A | Minimal `/login` to issue JWTs (replace with real auth later). |
| **Error handling** | None | Central error handler that hides stack traces in production. |
| **Config** | Hard‑coded values | `dotenv` reads `PORT`, `JWT_SECRET`, `CORS_ORIGINS`, `NODE_ENV`. |
| **HTTPS / TLS** | Not addressed in code | Recommendation to terminate TLS at a reverse‑proxy (NGINX/Traefik) – see section 4. |
| **Dependency management** | Not pinned | Add a `package.json` with exact versions (run `npm i --save-exact`). Use `npm audit` CI step. |

