### 3.2. Load Configuration from Environment (12‑factor)

```js
require('dotenv').config();   // .env file for local dev only

const PORT = process.env.PORT || 3000;
```

> **Why:** Hard‑coding ports, secrets, or DB strings makes the app inflexible and risks leaking secrets in source control.

### 3.3. Harden Express with Core Security Middleware

```js
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');

// Security HTTP headers
app.use(helmet());

// Enable CORS (restrict origins in production)
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',   // replace '*' with your client origin(s)
  methods: ['GET','POST','PUT','DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Basic rate‑limiting – protects against brute‑force & DoS
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter); // apply to sensitive routes
```

### 3.4. Parse & Validate Input (Future‑Proof)

Even though the current endpoints don’t accept a body, you’ll likely add POST/PUT routes later. Set up a robust validation pipeline now.

```js
const Joi = require('joi');

// Example schema for a "create user" endpoint
const createUserSchema = Joi.object({
  name: Joi.string().trim().min(2).max(100).required(),
  email: Joi.string().email().required(),
  password: Joi.string().min(12).required()
});

function validate(schema) {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, { abortEarly: false });
    if (error) {
      return res.status(400).json({ error: error.details.map(d => d.message) });
    }
    req.validated = value;
    next();
  };
}
```

Add body‑parser **before** the validation middleware:

```js
app.use(express.json({ limit: '1mb' })); // limits payload size
```

### 3.5. Add Authentication & Authorization

Use JWT (or any other robust token system). Example of a simple auth middleware:

```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.sendStatus(401);

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // payload should contain user ID, roles, etc.
    next();
  } catch (err) {
    return res.sendStatus(403);
  }
}

// Protect the /users endpoint (example: only admin can view)
app.get('/users', authenticate, (req, res) => {
  if (!req.user.roles.includes('admin')) return res.sendStatus(403);
  // … return user list …
});
```

> **Tip:** Store `JWT_SECRET` securely (e.g., via a secret manager or env var). Rotate periodically.

### 3.6. Enforce HTTPS & HSTS

If you serve behind a reverse‑proxy (Nginx, Cloud‑flare, etc.), the proxy should terminate TLS. However, you can still add HSTS headers:

```js
app.use(
  helmet.hsts({
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  })
);
```

If you decide to let Node handle TLS directly (for dev), wrap the server with `https.createServer`.

### 3.7. Implement Centralised Error Handling & Logging

```js
const morgan = require('morgan');

// Request logging (combined format is good for production)
app.use(morgan('combined'));

// Central error handler (must come after all routes)
app.use((err, req, res, next) => {
  console.error(err); // consider using a structured logger like Winston/Bunyan
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message
  });
});
```

### 3.8. Protect Against Server‑Side Request Forgery (SSRF)

When you add any endpoint that fetches external URLs (e.g., `GET /fetch?url=...`), enforce a whitelist and validate the URL with the native `URL` class:

```js
function isAllowedUrl(urlString) {
  try {
    const url = new URL(urlString);
    const allowedHosts = ['api.trusted.com', 'static.example.org'];
    return allowedHosts.includes(url.hostname);
  } catch (_) {
    return false;
  }
}
```

### 3.9. Security‑Headers Summary (Helmet)

`helmet()` already sets many headers, but you can fine‑tune:

```js
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],
      styleSrc:   ["'self'", 'https:'],
      imgSrc:     ["'self'", 'data:'],
      connectSrc:["'self'"],
      // add more as needed
    },
  })
);
```

### 3.10. Dependency Health Check (CI)

Add a script to your `package.json`:

```json
"scripts": {
  "start": "node app.js",
  "lint": "eslint .",
  "audit": "npm audit --audit-level=high",
  "test": "npm test"
}
```

