## Consolidated “Secure Boilerplate” for **app.js**

Below is a **rewritten version** that incorporates the above mitigations while preserving the original functionality.

```js
// app.js – Secure Express Boilerplate
require('dotenv').config();                // Load env vars (e.g., JWT secret, NODE_ENV)

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');
const winston   = require('winston');
const auth      = require('./security/middleware/auth'); // JWT auth (optional)

const app = express();

// ---------- Security Middleware ----------
app.use(helmet()); // sets X‑* headers, HSTS (if in prod), CSP, etc.

// CORS – only allow trusted origins (adjust as needed)
app.use(cors({
  origin: process.env.CORS_ORIGINS?.split(',') || ['https://myapp.example.com'],
  credentials: true,
}));

// Rate limiting – helps mitigate DoS / brute‑force
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100,                // limit each IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Logging ----------
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [new winston.transports.Console()],
});
app.use(morgan('combined', { stream: { write: msg => logger.info(msg.trim()) } }));

// ---------- Body parsing (future‑proof) ----------
app.use(express.json({ limit: '10kb' })); // JSON body size limit

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // Minimal health data – no internal secrets
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example of a protected endpoint
app.get('/users', auth, (req, res) => {
  // In a real app this would pull from a DB; for now static list
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]);
});

// ---------- Central error handler ----------
app.use((err, _req, res, _next) => {
  logger.error('Unhandled error', { message: err.message, stack: err.stack });
  // Never expose stack trace to the client in production
  const status = err.status || 500;
  const response = { error: 'Internal Server Error' };
  if (process.env.NODE_ENV !== 'production') {
    response.details = err.message;
  }
  res.status(status).json(response);
});

// ---------- Server start ----------
const PORT = process.env.PORT || 3000;

if (process.env.NODE_ENV === 'production') {
  // In prod we expect a reverse‑proxy (NGINX, ELB) handling TLS
  app.listen(PORT, () => logger.info(`HTTP server listening on ${PORT}`));
} else {
  // Development convenience – optional HTTPS
  const https = require('https');
  const fs    = require('fs');

  if (process.env.ENABLE_HTTPS === 'true') {
    const httpsOptions = {
      key:  fs.readFileSync('./certs/key.pem'),
      cert: fs.readFileSync('./certs/cert.pem')
    };
    https.createServer(httpsOptions, app).listen(PORT, () =>
      logger.info(`HTTPS dev server listening on ${PORT}`)
    );
  } else {
    app.listen(PORT, () => logger.info(`HTTP dev server listening on ${PORT}`));
  }
}

module.exports = app;
```

